"use client";

import { useLayoutEffect, useRef, useState, type CSSProperties, type PointerEvent } from "react";
import "../shared/inter";
import { firstGrapheme } from "../shared/initials";
import { useLoopTrack, useStaticTrack } from "../shared/use-loop-track";
import { testimonials } from "./testimonials";
import "./styles.css";

export { testimonials };
export type Testimonial = {
  quote: string;
  name: string;
  role?: string;
  company?: string;
  avatar?: string;
  rating?: number;
  verified?: boolean;
};

export type TestimonialWallProps = {
  items?: Testimonial[];
  columns?: 1 | 2 | 3;
  speed?: number;
  pauseOnHover?: boolean;
  label?: string;
  className?: string;
  appearance?: "clean" | "classic";
};

const pace = [1, -0.84, 1.12];
const initialOffset = [0, 0.42, 0.18];

function initials(name: string) {
  const words = name.trim().split(/\s+/);
  const letters = words.filter(word => /^\p{L}/u.test(word));
  const names = (letters.length ? letters : words).filter((word, i) => !i || !/^(jr|sr|i{1,3}|iv|v|vi|phd|md|esq)[.,]?$/i.test(word));
  const outer = names.length > 1 ? [names[0], names[names.length - 1]] : names;
  return outer.map(firstGrapheme).join("").toLocaleUpperCase() || "?";
}

function fullTextIfTruncated(event: PointerEvent<HTMLElement>) {
  const element = event.currentTarget;
  element.title = element.scrollHeight > element.clientHeight + 1 || element.scrollWidth > element.clientWidth + 1 ? element.textContent || "" : "";
}

function QuoteCard({ item, prefix, original, appearance }: {
  item: Testimonial; prefix: string; original: boolean; appearance: TestimonialWallProps["appearance"];
}) {
  const [brokenPhoto, setBrokenPhoto] = useState<string>();
  const rating = item.rating && Number.isFinite(item.rating) ? Math.max(1, Math.min(5, Math.round(item.rating))) : 0;
  const meta = [item.role?.trim(), item.company?.trim()].filter(Boolean).join("\u00a0· ");
  const avatarSize = appearance === "clean" ? 32 : 36;
  return (
    <li className={prefix + "__item"}>
      <figure className={prefix + "__card"} tabIndex={original ? 0 : undefined}>
        {rating > 0 && (
          <div className={prefix + "__stars"} role="img" aria-label={`Rated ${rating} out of 5`}>
            {Array.from({ length: 5 }, (_, i) => (
              <svg key={i} data-on={i < rating || undefined} viewBox="0 0 16 16" aria-hidden="true">
                <path d="M8 1.6l1.9 3.95 4.35.6-3.17 3.03.78 4.32L8 11.43 4.14 13.5l.78-4.32L1.75 6.15l4.35-.6L8 1.6z" />
              </svg>
            ))}
          </div>
        )}
        {item.quote.trim() && (
          <blockquote className={prefix + "__quote"}><p dir="auto" onPointerEnter={fullTextIfTruncated}>{item.quote.trim()}</p></blockquote>
        )}
        <figcaption className={prefix + "__who"}>
          {item.avatar && item.avatar !== brokenPhoto ? (
            // The distributable block accepts photo URLs without requiring a Next.js image loader.
            // eslint-disable-next-line @next/next/no-img-element
            <img className={prefix + "__avatar"} src={item.avatar} width={avatarSize} height={avatarSize} alt="" loading="lazy" decoding="async" draggable={false} onError={() => setBrokenPhoto(item.avatar)} />
          ) : (
            <span className={prefix + "__avatar " + prefix + "__avatar--initials"} aria-hidden="true">{initials(item.name)}</span>
          )}
          <span className={prefix + "__id"}>
            <span className={prefix + "__name"}>
              <span className={prefix + "__name-text"} dir="auto" onPointerEnter={fullTextIfTruncated}>{item.name.trim()}</span>
              {item.verified && (
                <svg className={prefix + "__verified"} viewBox="0 0 16 16" role="img" aria-label="Verified customer">
                  <circle cx="8" cy="8" r="7" />
                  <path d="M5.2 8.1l1.9 1.9 3.7-3.8" fill="none" stroke={appearance === "clean" ? "var(--ui-twc-card)" : "var(--ui-tw-card)"} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
              )}
            </span>
            {meta && <span className={prefix + "__meta"} dir="auto" onPointerEnter={fullTextIfTruncated}>{meta}</span>}
          </span>
        </figcaption>
      </figure>
    </li>
  );
}

function QuoteColumn({ items, prefix, index, speed, pauseOnHover, appearance }: {
  items: Testimonial[]; prefix: string; index: number; speed: number; pauseOnHover: boolean; appearance: TestimonialWallProps["appearance"];
}) {
  const { viewport, track, original, copies } = useLoopTrack({ axis: "y", velocity: speed * pace[index], start: initialOffset[index], pauseOnHover });
  return (
    <div className={prefix + "__col"} ref={viewport}>
      <div className={prefix + "__track"} ref={track}>
        {Array.from({ length: copies }, (_, copy) => (
          <ul key={copy} className={prefix + "__set"} aria-hidden={copy !== 1 || undefined} ref={copy === 1 ? original : undefined}>
            {items.map((item, index) => (
              <QuoteCard key={index + "-" + item.name} item={item} prefix={prefix} appearance={appearance} original={copy === 1} />
            ))}
          </ul>
        ))}
      </div>
    </div>
  );
}

export function KalosTestimonialWall({
  items = testimonials, columns = 3, speed = 28, pauseOnHover = true, label = "What customers say", className, appearance = "clean",
}: TestimonialWallProps) {
  const still = useStaticTrack();
  const region = useRef<HTMLDivElement>(null);
  const [fit, setFit] = useState(3);
  useLayoutEffect(() => {
    const view = region.current;
    if (!view) return;
    const measure = () => setFit(view.clientWidth >= 740 ? 3 : view.clientWidth >= 480 ? 2 : 1);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(view);
    return () => observer.disconnect();
  }, []);
  const count = Math.max(1, Math.min(fit, columns, items.length));
  const prefix = "kalos-testimonial-wall--" + appearance;
  const variable = appearance === "clean" ? "--ui-twc-cols" : "--ui-tw-cols";
  return (
    <div
      ref={region}
      role="region"
      aria-label={label}
      className={[prefix, className].filter(Boolean).join(" ")}
      data-empty={!items.length || undefined}
      data-cols={count}
      data-static={still || undefined}
      style={{ [variable]: count } as CSSProperties}
    >
      {items.length ? Array.from({ length: count }, (_, index) => {
        const cards = items.filter((_, i) => i % count === index);
        if (still) return (
          <div key={index} className={prefix + "__col"}>
            <ul className={prefix + "__set"}>
              {cards.map((item, i) => <QuoteCard key={i + "-" + item.name} item={item} prefix={prefix} appearance={appearance} original />)}
            </ul>
          </div>
        );
        return (
        <QuoteColumn
          key={index}
          prefix={prefix}
          items={cards}
          index={index}
          speed={speed}
          pauseOnHover={pauseOnHover}
          appearance={appearance}
        />
        );
      }) : <p className={prefix + "__empty"}>No quotes yet</p>}
    </div>
  );
}

export function KalosTestimonialWallPreview({ appearance = "clean" }: Pick<TestimonialWallProps, "appearance">) {
  return (
    <section className="kalos-testimonial-wall-preview" data-appearance={appearance}>
      <div className="kalos-testimonial-wall-preview__content">
        <header className="kalos-testimonial-wall-preview__head">
          <p>Testimonials</p>
          <h2>Loved by product teams</h2>
        </header>
        <KalosTestimonialWall items={testimonials} speed={26} appearance={appearance} label="What product teams say" />
      </div>
    </section>
  );
}

/* Adapted from affectUI, MIT. See LICENSE.txt. */
.kalos-testimonial-wall--classic {
  --ui-tw-card: var(--aui-surface, #ffffff);
  --ui-tw-line: var(--aui-border, #ececec);
  --ui-tw-ink: var(--aui-ink, #171717);
  --ui-tw-text: var(--aui-ink, #404040);
  --ui-tw-muted: var(--aui-muted, #8f8f8f);
  --ui-tw-faint: var(--aui-placeholder, #b5b5b5);
  --ui-tw-star: #a3a3a8;
  --ui-tw-star-off: #e2e2e5;
  --ui-tw-initials: #f0f0f1;
  --ui-tw-shadow: var(--aui-shadow-card, 0 0 0 1px var(--ui-tw-line), 0 1px 2px rgba(0, 0, 0, 0.04));
  --ui-tw-lift: 0 0 0 1px var(--ui-tw-line), 0 2px 4px rgba(0, 0, 0, 0.03), 0 12px 28px -10px rgba(0, 0, 0, 0.14);
  --ui-tw-focus: var(--aui-focus, rgba(0, 96, 226, 0.7));
  --ui-tw-gap: 16px;
  --ui-tw-fade: 96px;
  --ui-tw-dim: 0.62;
  --ui-tw-ease: var(--aui-ease, cubic-bezier(0.22, 1, 0.36, 1));
  container-type: inline-size;
  display: grid;
  grid-template-columns: repeat(var(--ui-tw-cols, 3), minmax(0, 1fr));
  grid-template-rows: minmax(0, 1fr);
  gap: var(--ui-tw-gap);
  width: 100%;
  min-width: 0;
  height: var(--ui-tw-height, 600px);
  padding-inline: 12px;
  box-sizing: border-box;
  overflow: hidden;
  -webkit-mask-image: linear-gradient(180deg, transparent, #000 var(--ui-tw-fade), #000 calc(100% - var(--ui-tw-fade)), transparent);
  mask-image: linear-gradient(180deg, transparent, #000 var(--ui-tw-fade), #000 calc(100% - var(--ui-tw-fade)), transparent);
  font-family: var(--aui-font, "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif);
  -webkit-font-smoothing: antialiased;
}

.kalos-testimonial-wall--classic[data-empty] { display: grid; place-items: center; height: auto; min-height: 160px; -webkit-mask-image: none; mask-image: none; }
.kalos-testimonial-wall--classic__empty { margin: 0; font-size: 14px; color: var(--ui-tw-muted); }

.kalos-testimonial-wall--classic__col {
  position: relative;
  min-width: 0;
  min-height: 0;
  height: 100%;
  cursor: grab;
  user-select: none;
  -webkit-user-select: none;
  -webkit-touch-callout: none;
}
.kalos-testimonial-wall--classic__col[data-dragging] { cursor: grabbing; }
.kalos-testimonial-wall--classic__track { will-change: transform; }
.kalos-testimonial-wall--classic__set {
  position: relative;
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
}
.kalos-testimonial-wall--classic__item { margin-bottom: var(--ui-tw-gap); }

.kalos-testimonial-wall--classic__card {
  display: flex;
  flex-direction: column;
  gap: 14px;
  margin: 0;
  padding: 18px 20px 18px;
  border-radius: var(--aui-radius-lg, 16px);
  background: var(--ui-tw-card);
  box-shadow: var(--ui-tw-shadow);
  color: var(--ui-tw-text);
  transition: transform 320ms var(--ui-tw-ease), box-shadow 320ms var(--ui-tw-ease), opacity 320ms var(--ui-tw-ease);
}
.kalos-testimonial-wall--classic__card:focus { outline: none; }
.kalos-testimonial-wall--classic__card:focus-visible { outline: 2px solid var(--ui-tw-focus); outline-offset: 2px; }

.kalos-testimonial-wall--classic__stars { display: flex; gap: 2px; margin-bottom: -4px; }
.kalos-testimonial-wall--classic__stars svg { width: 13px; height: 13px; fill: var(--ui-tw-star-off); }
.kalos-testimonial-wall--classic__stars svg[data-on] { fill: var(--ui-tw-star); }

.kalos-testimonial-wall--classic__quote { margin: 0; }
.kalos-testimonial-wall--classic__quote p {
  margin: 0;
  font-size: 14px;
  line-height: 1.6;
  letter-spacing: -0.006em;
  text-wrap: pretty;
  overflow-wrap: break-word;
  white-space: pre-line;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 10;
  line-clamp: 10;
  overflow: hidden;
}

.kalos-testimonial-wall--classic__who { display: flex; align-items: center; gap: 10px; min-width: 0; }
.kalos-testimonial-wall--classic__avatar {
  flex: none;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  object-fit: cover;
  background: var(--ui-tw-initials);
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.05);
  pointer-events: none;
}
.kalos-testimonial-wall--classic__avatar--initials {
  display: grid;
  place-items: center;
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.01em;
  color: var(--ui-tw-muted);
}
.kalos-testimonial-wall--classic__id { display: grid; gap: 1px; min-width: 0; }
.kalos-testimonial-wall--classic__name {
  display: flex;
  align-items: flex-start;
  gap: 5px;
  min-width: 0;
  font-size: 13.5px;
  font-weight: 500;
  line-height: 18px;
  color: var(--ui-tw-ink);
}
.kalos-testimonial-wall--classic__name-text {
  display: -webkit-box;
  min-width: 0;
  overflow: hidden;
  overflow-wrap: anywhere;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
}
.kalos-testimonial-wall--classic__verified { flex: none; margin-top: 2px; width: 14px; height: 14px; fill: var(--ui-tw-faint); }
.kalos-testimonial-wall--classic__meta {
  min-width: 0;
  overflow: hidden;
  overflow-wrap: anywhere;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  font-size: 12.5px;
  line-height: 17px;
  color: var(--ui-tw-muted);
}

@media (hover: hover) {
  .kalos-testimonial-wall--classic__col:not([data-dragging]) .kalos-testimonial-wall--classic__card:hover { transform: translateY(-3px); box-shadow: var(--ui-tw-lift); }
  .kalos-testimonial-wall--classic:has(.kalos-testimonial-wall--classic__col:not([data-dragging]) .kalos-testimonial-wall--classic__card:hover) .kalos-testimonial-wall--classic__card:not(:hover) { opacity: var(--ui-tw-dim); }
}
.kalos-testimonial-wall--classic__card:focus-visible { transform: translateY(-3px); box-shadow: var(--ui-tw-lift); }

@container (max-width: 479px) {
  .kalos-testimonial-wall--classic__card { padding: 18px 18px 18px; }
  .kalos-testimonial-wall--classic__quote p { font-size: 15px; line-height: 1.58; }
}
@container (max-width: 739px) {
  .kalos-testimonial-wall--classic__col { --ui-tw-gap: 14px; }
}

.kalos-testimonial-wall--classic[data-static] {
  height: auto;
  grid-template-rows: auto;
  overflow: visible;
  -webkit-mask-image: none;
  mask-image: none;
}
.kalos-testimonial-wall--classic[data-static] .kalos-testimonial-wall--classic__col { height: auto; cursor: auto; user-select: auto; -webkit-user-select: auto; }

@media (prefers-reduced-motion: reduce) {
  .kalos-testimonial-wall--classic__card { transition: none; }
}

:where(.dark, [data-theme="dark"]) .kalos-testimonial-wall--classic {
  --ui-tw-card: var(--aui-surface, #19191b);
  --ui-tw-line: var(--aui-border, #2a2a2e);
  --ui-tw-ink: var(--aui-ink, #ededed);
  --ui-tw-text: var(--aui-ink, #c8c8cc);
  --ui-tw-muted: var(--aui-muted, #8b8b92);
  --ui-tw-faint: var(--aui-placeholder, #6b6b72);
  --ui-tw-star: #7a7a82;
  --ui-tw-star-off: #2f2f34;
  --ui-tw-initials: #232327;
  --ui-tw-shadow: var(--aui-shadow-card, 0 0 0 1px var(--ui-tw-line));
  --ui-tw-lift: 0 0 0 1px #34343a, 0 12px 28px -10px rgba(0, 0, 0, 0.6);
  --ui-tw-focus: var(--aui-focus, rgba(77, 141, 255, 0.8));
}
:where(.dark, [data-theme="dark"]) .kalos-testimonial-wall--classic__avatar { box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.06); }

.kalos-testimonial-wall--clean {
  --ui-twc-card: var(--aui-surface, #ffffff);
  --ui-twc-title: var(--aui-ink, #000000);
  --ui-twc-text: var(--aui-ink, rgba(0, 0, 0, 0.88));
  --ui-twc-muted: var(--aui-muted, rgba(0, 0, 0, 0.45));
  --ui-twc-faint: var(--aui-placeholder, rgba(0, 0, 0, 0.27));
  --ui-twc-star: rgba(0, 0, 0, 0.36);
  --ui-twc-star-off: rgba(0, 0, 0, 0.08);
  --ui-twc-initials: #f5f5f5;
  --ui-twc-initials-ink: rgba(0, 0, 0, 0.45);
  --ui-twc-ring: rgba(0, 0, 0, 0.06);
  --ui-twc-shadow: var(--aui-shadow-card, 0 0 0 0.5px rgba(0, 0, 0, 0.06), 0 1px 1px -1px rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.05));
  --ui-twc-lift: 0 0 0 0.5px rgba(0, 0, 0, 0.06), 0 1px 1px -1px rgba(0, 0, 0, 0.1), 0 2px 4px 0 rgba(0, 0, 0, 0.04), 0 12px 24px -12px rgba(0, 0, 0, 0.12);
  --ui-twc-focus: var(--aui-focus, rgba(0, 96, 226, 0.7));
  --ui-twc-gap: 16px;
  --ui-twc-fade: 120px;
  --ui-twc-dim: 0.6;
  --ui-twc-ease: var(--aui-ease, cubic-bezier(0.22, 1, 0.36, 1));
  container-type: inline-size;
  display: grid;
  grid-template-columns: repeat(var(--ui-twc-cols, 3), minmax(0, 1fr));
  grid-template-rows: minmax(0, 1fr);
  gap: var(--ui-twc-gap);
  width: 100%;
  min-width: 0;
  height: var(--ui-twc-height, 600px);
  padding-inline: 12px;
  box-sizing: border-box;
  overflow: hidden;
  -webkit-mask-image: linear-gradient(180deg, transparent 0, rgba(0, 0, 0, 0.35) calc(var(--ui-twc-fade) * 0.4), #000 var(--ui-twc-fade), #000 calc(100% - var(--ui-twc-fade)), rgba(0, 0, 0, 0.35) calc(100% - var(--ui-twc-fade) * 0.4), transparent 100%);
  mask-image: linear-gradient(180deg, transparent 0, rgba(0, 0, 0, 0.35) calc(var(--ui-twc-fade) * 0.4), #000 var(--ui-twc-fade), #000 calc(100% - var(--ui-twc-fade)), rgba(0, 0, 0, 0.35) calc(100% - var(--ui-twc-fade) * 0.4), transparent 100%);
  font-family: var(--aui-font, "Inter", "InterVariable", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif);
  font-size: 13px;
  font-weight: 400;
  line-height: 20px;
  -webkit-font-smoothing: antialiased;
}
:where(.kalos-testimonial-wall--clean) *, :where(.kalos-testimonial-wall--clean) *::before, :where(.kalos-testimonial-wall--clean) *::after { box-sizing: border-box; }

.kalos-testimonial-wall--clean[data-empty] { display: grid; place-items: center; height: auto; min-height: 160px; -webkit-mask-image: none; mask-image: none; }
.kalos-testimonial-wall--clean .kalos-testimonial-wall--clean__empty { margin: 0; font-size: 13px; line-height: 20px; color: var(--ui-twc-muted); }

.kalos-testimonial-wall--clean__col {
  position: relative;
  min-width: 0;
  min-height: 0;
  height: 100%;
  cursor: grab;
  user-select: none;
  -webkit-user-select: none;
  -webkit-touch-callout: none;
}
.kalos-testimonial-wall--clean__col[data-dragging] { cursor: grabbing; }
.kalos-testimonial-wall--clean__track { will-change: transform; }
.kalos-testimonial-wall--clean .kalos-testimonial-wall--clean__set {
  position: relative;
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
}
.kalos-testimonial-wall--clean .kalos-testimonial-wall--clean__item { margin: 0 0 var(--ui-twc-gap); }

.kalos-testimonial-wall--clean .kalos-testimonial-wall--clean__card {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin: 0;
  padding: 20px;
  border-radius: calc(var(--aui-radius-lg, 10px) + 2px);
  background: var(--ui-twc-card);
  box-shadow: var(--ui-twc-shadow);
  color: var(--ui-twc-text);
  transition: transform 320ms var(--ui-twc-ease), box-shadow 320ms var(--ui-twc-ease), opacity 320ms var(--ui-twc-ease);
}
.kalos-testimonial-wall--clean__card:focus { outline: none; }
.kalos-testimonial-wall--clean__card:focus-visible { outline: 2px solid var(--ui-twc-focus); outline-offset: 2px; }

.kalos-testimonial-wall--clean .kalos-testimonial-wall--clean__stars { display: flex; gap: 2px; margin-bottom: -6px; }
.kalos-testimonial-wall--clean__stars svg { display: block; width: 12px; height: 12px; fill: var(--ui-twc-star-off); }
.kalos-testimonial-wall--clean__stars svg[data-on] { fill: var(--ui-twc-star); }

.kalos-testimonial-wall--clean .kalos-testimonial-wall--clean__quote { margin: 0; }
.kalos-testimonial-wall--clean .kalos-testimonial-wall--clean__quote p {
  margin: 0;
  font-size: 14px;
  font-weight: 400;
  line-height: 22px;
  letter-spacing: -0.084px;
  color: var(--ui-twc-text);
  text-wrap: pretty;
  overflow-wrap: break-word;
  white-space: pre-line;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 10;
  line-clamp: 10;
  overflow: hidden;
}

.kalos-testimonial-wall--clean .kalos-testimonial-wall--clean__who { display: flex; align-items: center; gap: 10px; min-width: 0; margin: 0; }
.kalos-testimonial-wall--clean__avatar {
  flex: none;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  object-fit: cover;
  background: var(--ui-twc-initials);
  box-shadow: 0 0 0 0.5px var(--ui-twc-ring);
  pointer-events: none;
}
.kalos-testimonial-wall--clean__avatar--initials {
  display: grid;
  place-items: center;
  font-size: 12px;
  font-weight: 500;
  line-height: 16px;
  color: var(--ui-twc-initials-ink);
}
.kalos-testimonial-wall--clean__id { display: grid; gap: 0; min-width: 0; }
.kalos-testimonial-wall--clean__name {
  display: flex;
  align-items: flex-start;
  gap: 4px;
  min-width: 0;
  font-size: 13px;
  font-weight: 500;
  line-height: 20px;
  color: var(--ui-twc-title);
}
